from selenium import webdriver                                           # Library untuk otomasi browser
from selenium.webdriver.common.by import By                              # Untuk menentukan cara mencari elemen (XPATH, CSS, dll)
from selenium.webdriver.chrome.service import Service                    # Untuk menjalankan ChromeDriver sebagai service
from selenium.webdriver.support.ui import WebDriverWait                  # Untuk menunggu elemen muncul di halaman
from selenium.webdriver.support import expected_conditions as EC         # Kondisi yang ditunggu (elemen muncul, bisa diklik, dll)
from webdriver_manager.chrome import ChromeDriverManager                 # Auto-download ChromeDriver yang sesuai versi Chrome
import pandas as pd                                                       # Untuk membaca/menulis file CSV
import time                                                               # Untuk memberi jeda waktu (sleep)
import random                                                             # Untuk jeda waktu acak agar tidak terdeteksi bot
import os                                                                 # Untuk cek apakah file CSV sudah ada

NAMA_FILE_CSV = "tokopedia_baru.csv"                                     # Nama file output CSV
MIN_ULASAN    = 999                                                       # Batas minimum ulasan (produk >= 999 di-skip)

# ── Load data lama ──────────────────────────
if os.path.exists(NAMA_FILE_CSV):                                        # Cek apakah file CSV sudah ada
    df_lama      = pd.read_csv(NAMA_FILE_CSV)                            # Baca file CSV lama ke DataFrame
    all_reviews  = df_lama.to_dict("records")                            # Ubah DataFrame jadi list of dict
    seen_keys    = set(                                                   # Buat set berisi key unik tiap ulasan
        f"{r['nama_produk']}|{r['username']}|{str(r['ulasan'])[:50]}"   # Key = nama produk + username + 50 karakter pertama ulasan
        for r in all_reviews                                              # Loop semua ulasan yang sudah ada
    )
    print(f" Data lama dimuat: {len(all_reviews)} ulasan")               # Info berapa ulasan yang sudah ada
else:                                                                     # Kalau file belum ada
    all_reviews = []                                                      # Mulai dengan list kosong
    seen_keys   = set()                                                   # Set kosong (belum ada ulasan)
    print("  File lama tidak ditemukan, mulai dari awal")                # Info mulai dari nol

# ── Hitung ulasan per produk ─────────────────
ulasan_per_produk = {}                                                    # Dict untuk menyimpan jumlah ulasan per produk
for r in all_reviews:                                                     # Loop semua ulasan
    ulasan_per_produk[r["nama_produk"]] = ulasan_per_produk.get(r["nama_produk"], 0) + 1  # Tambah hitungan per produk

# ── Filter produk yang akan di-scrape ────────
MULAI_DARI = "Vitamin D3K2 5000IU 60 Kapsul"                            # Nama produk awal scraping (ganti sesuai kebutuhan)

start_index = next(                                                       # Cari posisi produk MULAI_DARI di list
    (i for i, (_, name, _) in enumerate(product_urls) if name == MULAI_DARI), 0  # Kalau tidak ketemu, mulai dari index 0
)

todo = [(url, name, kat) for url, name, kat in product_urls[start_index:]  # Ambil produk dari posisi MULAI_DARI ke bawah
        if ulasan_per_produk.get(name, 0) == 0]                            # Hanya yang belum ada ulasan sama sekali

print(f"\n {len(todo)} produk akan di-scrape:")                          # Info berapa produk yang akan di-scrape
for _, name, kat in todo:                                                 # Loop tiap produk
    print(f"   [{kat}] {name} → sudah {ulasan_per_produk.get(name, 0)} ulasan")  # Tampilkan nama dan jumlah ulasan

# ── Setup Selenium ───────────────────────────
options = webdriver.ChromeOptions()                                       # Buat objek pengaturan Chrome
options.add_argument("--start-maximized")                                 # Buka browser dalam mode layar penuh
options.add_argument("--disable-blink-features=AutomationControlled")    # Sembunyikan tanda bahwa browser dikontrol otomatis
options.add_experimental_option("excludeSwitches", ["enable-automation"]) # Hapus flag "automation" dari Chrome
options.add_experimental_option("useAutomationExtension", False)          # Nonaktifkan ekstensi otomasi Chrome

driver = webdriver.Chrome(                                                # Buat instance browser Chrome
    service=Service(ChromeDriverManager().install()),                     # Auto-install ChromeDriver yang cocok
    options=options                                                        # Pakai pengaturan yang sudah dibuat
)
driver.set_page_load_timeout(90)                                          # Batas waktu load halaman: 90 detik
wait = WebDriverWait(driver, 20)                                          # Buat objek wait dengan timeout 20 detik

# ── Fungsi filter rating ─────────────────────
def klik_filter_rating(rating):                                           # Fungsi untuk klik filter bintang tertentu
    try:
        driver.execute_script("window.scrollTo(0, 400)")                 # Scroll ke posisi filter rating
        time.sleep(1)                                                     # Tunggu scroll selesai
        result = driver.execute_script(f"""
            let allFilters = document.querySelectorAll("[data-testid='ratingFilter'] input");  // Cari semua checkbox filter rating
            allFilters.forEach(f => {{ if(f.checked) f.click(); }});                          // Uncheck semua filter yang aktif
            let labels = [...document.querySelectorAll("label.checkbox")];                    // Ambil semua label checkbox
            let target = labels.find(l => l.innerText.trim() === '{rating}');                 // Cari label yang sesuai rating
            if(target) {{ target.click(); return true; }}                                     // Klik label tersebut
            return false;                                                                      // Return false kalau tidak ketemu
        """)
        time.sleep(3)                                                     # Tunggu halaman reload setelah filter
        if result:
            print(f"    Filter rating {rating} aktif")                   # Info filter berhasil diklik
        else:
            print(f"    Filter rating {rating} tidak ditemukan")         # Info filter tidak ketemu
        return result                                                     # Return True/False
    except Exception as e:
        print(f"    Error filter: {e}")                                  # Tampilkan error kalau ada
        return False                                                      # Return False kalau error

# ── Fungsi scrape per produk ─────────────────
def scrape_ulasan(product_url, product_name, kategori):                  # Fungsi utama scraping per produk
    sudah = ulasan_per_produk.get(product_name, 0)                       # Ambil jumlah ulasan yang sudah ada
    print(f"\n {product_name[:50]} (sudah: {sudah})")                   # Tampilkan nama produk dan jumlah ulasan
    try:
        driver.get(product_url)                                          # Buka halaman produk di browser
        time.sleep(random.uniform(6, 9))                                 # Tunggu 6-9 detik acak supaya tidak terdeteksi bot
    except:
        print("   Timeout, skip")                                        # Kalau timeout, lewati produk ini
        return

    for i in range(6):                                                   # Scroll halaman 6 kali
        driver.execute_script(f"window.scrollTo(0, {(i+1)*500})")       # Scroll bertahap 500px per langkah
        time.sleep(1)                                                    # Tunggu 1 detik tiap scroll

    clicked = False                                                      # Flag apakah tab ulasan berhasil diklik
    try:
        els = driver.find_elements(By.XPATH, "//*[contains(text(),'Ulasan')]")  # Cari semua elemen yang ada teks "Ulasan"
        for el in els:                                                   # Loop tiap elemen yang ditemukan
            try:
                if el.is_displayed() and el.tag_name in ["div", "span", "button", "a"]:  # Pastikan elemen terlihat dan tipe yang benar
                    driver.execute_script("arguments[0].click();", el)  # Klik elemen via JavaScript
                    time.sleep(3)                                        # Tunggu tab ulasan load
                    clicked = True                                       # Tandai berhasil klik
                    print("    Tab ulasan diklik")                       # Info berhasil
                    break                                                # Berhenti setelah berhasil klik
            except:
                continue                                                 # Kalau gagal, coba elemen berikutnya
    except:
        pass

    if not clicked:                                                      # Kalau tab ulasan tidak ketemu
        print("    Tab ulasan tidak ditemukan")                         # Info gagal
        return                                                           # Keluar dari fungsi, skip produk ini

    rating_pages = {5: 3, 4: 3, 3: 5, 2: 5, 1: 5}                     # Jumlah halaman yang di-scrape per rating bintang
    for rating, max_page in rating_pages.items():                       # Loop tiap rating (5, 4, 3, 2, 1)
        print(f"\n    Rating {rating}...")                               # Info rating yang sedang diproses
        klik_filter_rating(rating)                                       # Aktifkan filter rating
        time.sleep(2)                                                    # Tunggu filter aktif

        for page in range(1, max_page + 1):                             # Loop tiap halaman sesuai max_page
            time.sleep(3)                                                # Tunggu halaman ulasan load

            review_els = driver.find_elements(By.XPATH, "//*[@data-testid='lblItemUlasan']")  # Ambil semua elemen teks ulasan
            user_els   = driver.find_elements(By.CSS_SELECTOR, "span.name")                   # Ambil semua elemen nama user
            date_els   = driver.find_elements(By.CSS_SELECTOR, "p.css-1rpz5os-unf-heading")   # Ambil semua elemen tanggal ulasan

            if not review_els:                                           # Kalau tidak ada ulasan di halaman ini
                print(f"      Halaman {page}: tidak ada ulasan")        # Info halaman kosong
                break                                                    # Berhenti, lanjut rating berikutnya

            baru = 0                                                     # Counter ulasan baru di halaman ini
            for i in range(len(review_els)):                            # Loop tiap ulasan yang ditemukan
                try:
                    ulasan_text   = review_els[i].text                  # Ambil teks ulasan
                    username_text = user_els[i].text if i < len(user_els) else ""   # Ambil username (kalau ada)
                    tanggal_text  = date_els[i].text if i < len(date_els) else ""   # Ambil tanggal (kalau ada)

                    key = f"{product_name}|{username_text}|{ulasan_text[:50]}"      # Buat key unik untuk cek duplikat
                    if key in seen_keys:                                 # Kalau ulasan ini sudah pernah disimpan
                        continue                                         # Skip, jangan simpan lagi

                    seen_keys.add(key)                                   # Tambahkan key ke set supaya tidak duplikat
                    all_reviews.append({                                 # Tambahkan ulasan ke list
                        "nama_produk": product_name,                    # Nama produk
                        "kategori"   : kategori,                        # Kategori produk
                        "username"   : username_text,                   # Username pembeli
                        "rating"     : str(rating),                     # Rating bintang
                        "ulasan"     : ulasan_text,                     # Teks ulasan
                        "tanggal"    : tanggal_text,                    # Tanggal ulasan
                    })
                    baru += 1                                            # Tambah counter ulasan baru
                except:
                    continue                                             # Kalau error di satu ulasan, lanjut ke berikutnya

            print(f"      Halaman {page}: +{baru} baru | Total: {len(all_reviews)}")  # Info hasil scrape halaman ini
            pd.DataFrame(all_reviews).to_csv(NAMA_FILE_CSV, index=False)              # Simpan ke CSV setiap selesai satu halaman

            try:
                next_btn = driver.find_element(By.XPATH, "//*[@aria-label='Laman berikutnya']")  # Cari tombol next page
                driver.execute_script("arguments[0].click();", next_btn)                          # Klik tombol next
                time.sleep(random.uniform(2, 4))                                                  # Tunggu 2-4 detik acak
            except:
                break                                                    # Kalau tombol next tidak ada, stop pindah halaman

        klik_filter_rating(rating)                                       # Reset/uncheck filter rating setelah selesai
        time.sleep(2)                                                    # Tunggu reset filter

# ── Jalankan ─────────────────────────────────
print(f"\n Mulai scraping {len(todo)} produk...")                        # Info mulai scraping
print("   Jangan tutup browser!\n")                                      # Peringatan jangan tutup browser

try:
    for url, name, kategori in todo:                                     # Loop tiap produk yang akan di-scrape
        scrape_ulasan(url, name, kategori)                               # Jalankan scraping untuk produk ini
        ulasan_per_produk[name] = sum(1 for r in all_reviews if r["nama_produk"] == name)  # Update hitungan ulasan produk
        time.sleep(random.uniform(5, 10))                                # Jeda 5-10 detik antar produk

finally:                                                                  # Blok ini selalu dijalankan meski ada error
    driver.quit()                                                         # Tutup browser
    df = pd.DataFrame(all_reviews) if all_reviews else pd.DataFrame()    # Ubah list ulasan jadi DataFrame
    df.to_csv(NAMA_FILE_CSV, index=False)                                 # Simpan final ke CSV
    print(f"\n Selesai! Total: {len(df)} ulasan")                        # Info total ulasan
    print("\nPer kategori:")                                              # Header tabel per kategori
    print(df.groupby("kategori").size().reset_index(name="jumlah_ulasan").to_string(index=False))  # Tampilkan jumlah ulasan per kategori